+  // Output pane: wrap each interpolation's run, tagged by its template span (data→output).
   const bytes = enc.encode(insp.output || "");
   const interps = [...(insp.interpolations || [])].sort((a,b) => a.out[0] - b.out[0]);
   let html = "", pos = 0;
   for (const it of interps) {
     if (it.out[0] < pos) continue;
