     const tip = `${it.value}  ·  template ${it.src[0]}–${it.src[1]}`;
-    html += `<span class="interp" title="${tip.replace(/"/g,"&quot;")}">` + esc(dec.decode(bytes.slice(it.out[0], it.out[1]))) + `</span>`;
+    html += `<span class="interp" data-src="${key(it.src)}" title="${tip.replace(/"/g,"&quot;")}">`
+      + esc(dec.decode(bytes.slice(it.out[0], it.out[1]))) + `</span>`;
     pos = it.out[1];
   }
   html += esc(dec.decode(bytes.slice(pos)));
