-  $("#rust").textContent = insp.emittedRust ?? ("// emit error: " + (insp.emitError || ""));
+
+  // Rust pane: wrap the byte range of each interpolation's emitted Rust (template→Rust),
+  // tagged by the SAME template span — so output↔Rust link by source span.
+  const rust = insp.emittedRust ?? null;
+  if (rust === null) {
+    $("#rust").textContent = "// emit error: " + (insp.emitError || "");
+  } else {
+    const rb = enc.encode(rust);
+    const srcKeys = new Set(interps.map(i => key(i.src)));
+    const tiles = (insp.rustMap || [])
+      .filter(t => srcKeys.has(key(t.src)))
+      .sort((a,b) => a.rust[0] - b.rust[0]);
+    let rh = "", rp = 0;
+    for (const t of tiles) {
+      if (t.rust[0] < rp) continue;
+      rh += esc(dec.decode(rb.slice(rp, t.rust[0])));
+      rh += `<span class="rtile" data-src="${key(t.src)}">` + esc(dec.decode(rb.slice(t.rust[0], t.rust[1]))) + `</span>`;
+      rp = t.rust[1];
+    }
+    rh += esc(dec.decode(rb.slice(rp)));
+    $("#rust").innerHTML = rh;
+  }
   status(`${interps.length} interpolation(s)`);
 }

+// Cross-pane linking: hover any span with data-src → highlight every span (output + Rust)
+// from the same template span.
+function linkHover(e) {
+  const src = e.target.dataset.src;
+  if (!src) return;
+  const on = e.type === "mouseover";
+  document.querySelectorAll(`[data-src="${src}"]`).forEach(el => el.classList.toggle("link-hi", on));
+}
+$("#output").addEventListener("mouseover", linkHover);
+$("#output").addEventListener("mouseout", linkHover);
+$("#rust").addEventListener("mouseover", linkHover);
+$("#rust").addEventListener("mouseout", linkHover);
